{"explanation":"Arrange four identical right triangles, with legs a and b and hypotenuse c, inside a square of side a+b; the uncovered central square has area c². Slide the same triangles into two rectangular pairs, leaving two squares with total area a²+b². Because neither the outer square nor the total triangle area changes, the uncovered areas are equal: c² = a²+b².","manimCode":"const a = 3;
const b = 2;
const side = a + b;
const sc = 0.78;
const origin = [-4.05, -1.95, 0];
const pt = (x, y) => [origin[0] + sc * x, origin[1] + sc * y, 0];

const heading = new Text({ text: 'Pythagoras: a proof by rearrangement', color: WHITE, fontSize: 30 });
heading.moveTo([0, 3.2, 0]);
const instruction = new Text({ text: 'Same outer square. Same four triangles. Same uncovered area.', color: GRAY, fontSize: 20 });
instruction.moveTo([0, -3.15, 0]);

const boundary = new Polygon({ vertices: [pt(0, 0), pt(side, 0), pt(side, side), pt(0, side)], color: WHITE });
boundary.setFillOpacity(0);
boundary.setStrokeWidth(3);

const configurations = [
  [[0, 0], [a, 0], [0, b]],
  [[side, 0], [side, a], [a, 0]],
  [[side, side], [b, side], [side, a]],
  [[0, side], [0, b], [b, side]]
];
const palette = [BLUE, TEAL, BLUE_D, PURPLE];
const triangles = configurations.map((vertices, index) => {
  const tri = new Polygon({ vertices: vertices.map(([x, y]) => pt(x, y)), color: palette[index] });
  tri.setFill(palette[index], 0.8);
  tri.setStrokeWidth(2);
  return tri;
});

const centralSquare = new Polygon({ vertices: [pt(a, 0), pt(side, a), pt(b, side), pt(0, b)], color: YELLOW });
centralSquare.setFill(YELLOW, 0.18);
centralSquare.setStrokeWidth(3);
const cLabel = new MathTex({ latex: 'c^2' });
await cLabel.waitForRender();
cLabel.setColor(YELLOW);
cLabel.moveTo(pt(side / 2, side / 2));
const firstGap = new VGroup(centralSquare, cLabel);

const aSquare = new Polygon({ vertices: [pt(0, b), pt(a, b), pt(a, side), pt(0, side)], color: YELLOW });
aSquare.setFill(YELLOW, 0.18);
aSquare.setStrokeWidth(3);
const bSquare = new Polygon({ vertices: [pt(a, 0), pt(side, 0), pt(side, b), pt(a, b)], color: YELLOW });
bSquare.setFill(YELLOW, 0.18);
bSquare.setStrokeWidth(3);
const aLabel = new MathTex({ latex: 'a^2' });
const bLabel = new MathTex({ latex: 'b^2' });
await aLabel.waitForRender();
await bLabel.waitForRender();
aLabel.setColor(YELLOW);
bLabel.setColor(YELLOW);
aLabel.moveTo(pt(a / 2, b + a / 2));
bLabel.moveTo(pt(a + b / 2, b / 2));
const secondGap = new VGroup(aSquare, bSquare, aLabel, bLabel);

const sideLabel = new MathTex({ latex: 'a+b' });
await sideLabel.waitForRender();
sideLabel.scale(0.7);
sideLabel.moveTo([-2.1, -2.3, 0]);

const formulaOne = new MathTex({ latex: '(a+b)^2=c^2+4\\left(\\frac{ab}{2}\\right)' });
const formulaTwo = new MathTex({ latex: '(a+b)^2=a^2+b^2+4\\left(\\frac{ab}{2}\\right)' });
const conclusion = new MathTex({ latex: '\\boxed{c^2=a^2+b^2}' });
await formulaOne.waitForRender();
await formulaTwo.waitForRender();
await conclusion.waitForRender();
formulaOne.scale(0.62).moveTo([2.9, 0.85, 0]);
formulaTwo.scale(0.62).moveTo([2.9, -0.05, 0]);
conclusion.scale(0.9).moveTo([2.9, -1.5, 0]);
conclusion.setColor(YELLOW);
const cancelCaption = new Text({ text: 'Subtract the same triangle area', color: GRAY, fontSize: 19 });
cancelCaption.moveTo([2.9, -0.85, 0]);

scene.add(heading, instruction);
await scene.play(new Create(boundary));
await scene.play(new AnimationGroup(triangles.map(tri => new DrawBorderThenFill(tri))));
await scene.play(new AnimationGroup([new FadeIn(firstGap), new Write(sideLabel), new Write(formulaOne)]));
await scene.wait(1.5);

let secondLayout = false;
let busy = false;
const displacement = [[0, 0, 0], [0, sc * b, 0], [-sc * b, -sc * a, 0], [sc * a, 0, 0]];
async function toggleArrangement() {
  if (busy) return;
  busy = true;
  const oldGap = secondLayout ? secondGap : firstGap;
  const nextGap = secondLayout ? firstGap : secondGap;
  await scene.play(new FadeOut(oldGap));
  scene.remove(oldGap);
  const sign = secondLayout ? -1 : 1;
  await scene.play(new AnimationGroup(triangles.slice(1).map((tri, index) => new Shift(tri, { direction: displacement[index + 1].map(v => sign * v) }))));
  await scene.play(new FadeIn(nextGap));
  secondLayout = !secondLayout;
  busy = false;
}

await toggleArrangement();
await scene.play(new Write(formulaTwo));
await scene.play(new AnimationGroup([new FadeIn(cancelCaption), new Write(conclusion)]));

const controls = new Controls(scene, { position: 'top-right', width: 210 });
controls.addButton({ label: 'Rearrange the triangles', onClick: () => { toggleArrangement(); } });
triangles.forEach(tri => makeHoverable(tri, scene, { hoverScale: 1, hoverOpacity: 1 }));
await scene.wait(999999);"}

